// Prepare ClinicalTrials.gov API request
const companies = $input.all();
const requests = [];

for (const company of companies) {
  const companyName = company.json.name;
  const companyId = company.json.id;

  // Build API URL for ClinicalTrials.gov
  const apiUrl = 'https://clinicaltrials.gov/api/v2/studies';
  const params = new URLSearchParams({
    'query.term': companyName,
    'filter.overallStatus': 'RECRUITING,ACTIVE_NOT_RECRUITING,COMPLETED,SUSPENDED,TERMINATED',
    'pageSize': '50',
    'format': 'json'
  });

  requests.push({
    company_id: companyId,
    company_name: companyName,
    url: `${apiUrl}?${params.toString()}`,
    method: 'GET'
  });
}

return requests.map(r => ({ json: r }));

// Parse ClinicalTrials.gov API response
const response = $input.first().json;
const companyId = $node['Prepare API Requests'].json.company_id;

const trials = [];

try {
  const studies = response.studies || [];

  for (const study of studies) {
    const protocolSection = study.protocolSection || {};
    const identificationModule = protocolSection.identificationModule || {};
    const statusModule = protocolSection.statusModule || {};
    const designModule = protocolSection.designModule || {};
    const sponsorCollaboratorsModule = protocolSection.sponsorCollaboratorsModule || {};
    const conditionsModule = protocolSection.conditionsModule || {};
    const armsInterventionsModule = protocolSection.armsInterventionsModule || {};
    const outcomesModule = protocolSection.outcomesModule || {};

    trials.push({
      company_id: companyId,
      nct_id: identificationModule.nctId,
      title: identificationModule.briefTitle,
      status: statusModule.overallStatus,
      phase: designModule.phases ? designModule.phases.join(', ') : null,
      study_type: designModule.studyType,
      start_date: statusModule.startDateStruct?.date || null,
      completion_date: statusModule.completionDateStruct?.date || null,
      primary_completion_date: statusModule.primaryCompletionDateStruct?.date || null,
      enrollment: statusModule.enrollmentInfo?.count || null,
      enrollment_actual: statusModule.enrollmentInfo?.type === 'ACTUAL' ? statusModule.enrollmentInfo.count : null,
      primary_outcome: outcomesModule.primaryOutcomes ? JSON.stringify(outcomesModule.primaryOutcomes) : null,
      secondary_outcome: outcomesModule.secondaryOutcomes ? JSON.stringify(outcomesModule.secondaryOutcomes) : null,
      conditions: conditionsModule.conditions || [],
      interventions: armsInterventionsModule.interventions ? armsInterventionsModule.interventions.map(i => i.name) : [],
      sponsors: [sponsorCollaboratorsModule.leadSponsor?.name] || [],
      collaborators: sponsorCollaboratorsModule.collaborators ? sponsorCollaboratorsModule.collaborators.map(c => c.name) : [],
      last_updated: statusModule.lastUpdatePostDateStruct?.date || new Date().toISOString(),
      raw_data: JSON.stringify(study)
    });
  }

  console.log(`Parsed ${trials.length} clinical trials`);

} catch (error) {
  console.error('Error parsing trials:', error.message);
}

return trials.map(t => ({ json: t }));

// Detect significant trial changes
const trials = $input.all();
const alerts = [];

for (const trial of trials) {
  const data = trial.json;

  // Check for critical status changes
  const isCritical = 
    data.status === 'TERMINATED' ||
    data.status === 'SUSPENDED' ||
    data.status === 'COMPLETED';

  // Check for large enrollment trials
  const isLargeEnrollment = data.enrollment && data.enrollment > 500;

  // Check for Phase 3 or Phase 4 trials
  const isLatePhaseTrial = data.phase && (data.phase.includes('3') || data.phase.includes('4'));

  if (isCritical || (isLargeEnrollment && isLatePhaseTrial)) {
    alerts.push({
      company_id: data.company_id,
      alert_type: 'clinical_trial_update',
      priority: isCritical ? 'high' : 'medium',
      title: `Trial ${data.status}: ${data.title}`,
      description: `NCT ID: ${data.nct_id} | Status: ${data.status} | Phase: ${data.phase || 'N/A'} | Enrollment: ${data.enrollment || 'N/A'}`,
      data: JSON.stringify(data),
      action_url: `https://clinicaltrials.gov/study/${data.nct_id}`,
      created_at: new Date().toISOString()
    });
  }
}

if (alerts.length > 0) {
  return alerts.map(a => ({ json: a }));
} else {
  return [];
}
